        item_cd text, item_nm text, ctgry_cd text, ctgry_nm text, se_cd text, se_nm text, vrty_cd text, vrty_nm text, grd_cd text, grd_nm text, unit text, unit_sz numeric, price_basis text
    )
    WHERE i.item_cd = r.item_cd AND i.price_basis = r.price_basis
        AND i.item_nm = r.item_nm AND i.ctgry_nm = r.ctgry_nm;
    ALTER TABLE ingredient
        ALTER COLUMN ctgry_cd SET NOT NULL,
        ALTER COLUMN se_cd SET NOT NULL,
        ALTER COLUMN se_nm SET NOT NULL,
        ALTER COLUMN vrty_cd SET NOT NULL,
        ALTER COLUMN vrty_nm SET NOT NULL,
        ALTER COLUMN grd_cd SET NOT NULL,
        ALTER COLUMN grd_nm SET NOT NULL,
        ALTER COLUMN unit SET NOT NULL,
        ALTER COLUMN unit_sz SET NOT NULL,
        ADD CONSTRAINT ingredient_source_valid CHECK (
            btrim(item_cd) <> '' AND btrim(item_nm) <> '' AND btrim(ctgry_cd) <> '' AND btrim(ctgry_nm) <> '' AND btrim(se_cd) <> '' AND btrim(se_nm) <> '' AND btrim(vrty_cd) <> '' AND btrim(vrty_nm) <> '' AND btrim(grd_cd) <> '' AND btrim(grd_nm) <> '' AND btrim(unit) <> ''
            AND unit_sz > 0 AND unit_sz <> 'NaN'::numeric AND unit_sz <> 'Infinity'::numeric
        ),
        DROP COLUMN price_basis;
    COMMENT ON TABLE ingredient IS '품목별 대표 거래 구분·품종·등급·규격 (aT API 원본 필드)';
    COMMENT ON COLUMN ingredient.unit_sz IS 'API 판매 단위 크기; price는 unit_sz × unit 기준';
END
